module optimized_blacklist (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] addr_i [0:7],\n    input [3:0] mask_i [0:7],\n    input [7:0] sign_i,\n    input [7:0] valid_i,\n    output reg [7:0] result_addr [0:7],\n    output reg [3:0] result_mask [0:7],\n    output reg [3:0] result_count,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] PARSE = 3'd1;\n    localparam [2:0] CHECK = 3'd2;\n    localparam [2:0] COMPUTE = 3'd3;\n    localparam [2:0] OUTPUT = 3'd4;\n    \n    reg [2:0] state, next_state;\n    \n    // Storage registers\n    reg [7:0] black_start [0:7];\n    reg [7:0] black_end [0:7];\n    reg [7:0] white_start [0:7];\n    reg [7:0] white_end [0:7];\n    reg [2:0] black_count;\n    reg [2:0] white_count;\n    \n    // Temporary registers\n    reg [7:0] temp_start;\n    reg [7:0] temp_end;\n    reg [2:0] idx;\n    reg conflict;\n    integer i, j;\n\n    // Next state logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n    \n    // State transition logic\n    always @(*) begin\n        case (state)\n            IDLE: next_state = start ? PARSE : IDLE;\n            PARSE: next_state = (idx == 3'd7) ? CHECK : PARSE;\n            CHECK: next_state = conflict ? OUTPUT : COMPUTE;\n            COMPUTE: next_state = OUTPUT;\n            OUTPUT: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n    \n    // Main logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all arrays\n            for (i = 0; i < 8; i = i + 1) begin\n                black_start[i] <= 8'd0;\n                black_end[i] <= 8'd0;\n                white_start[i] <= 8'd0;\n                white_end[i] <= 8'd0;\n                result_addr[i] <= 8'd0;\n                result_mask[i] <= 4'd0;\n            end\n            black_count <= 3'd0;\n            white_count <= 3'd0;\n            idx <= 3'd0;\n            conflict <= 1'b0;\n            result_count <= 4'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    idx <= 3'd0;\n                    conflict <= 1'b0;\n                    black_count <= 3'd0;\n                    white_count <= 3'd0;\n                    // Clear result arrays\n                    for (i = 0; i < 8; i = i + 1) begin\n                        result_addr[i] <= 8'd0;\n                        result_mask[i] <= 4'd0;\n                    end\n                end\n                \n                PARSE: begin\n                    if (valid_i[idx]) begin\n                        if (sign_i[idx] == 1'b0) begin // Black\n                            black_start[black_count] <= addr_i[idx] & (8'hFF << (8 - mask_i[idx]));\n                            black_end[black_count] <= addr_i[idx] | (8'hFF >> mask_i[idx]);\n                            black_count <= black_count + 3'd1;\n                        end else begin // White\n                            white_start[white_count] <= addr_i[idx] & (8'hFF << (8 - mask_i[idx]));\n                            white_end[white_count] <= addr_i[idx] | (8'hFF >> mask_i[idx]);\n                            white_count <= white_count + 3'd1;\n                        end\n                    end\n                    idx <= idx + 3'd1;\n                end\n                \n                CHECK: begin\n                    conflict <= 1'b0;\n                    if (black_count > 0 && white_count > 0) begin\n                        for (i = 0; i < black_count; i = i + 1) begin\n                            for (j = 0; j < white_count; j = j + 1) begin\n                                if ((black_start[i] <= white_end[j]) && (black_end[i] >= white_start[j]))\n                                    conflict <= 1'b1;\n                            end\n                        end\n                    end\n                end\n                \n                COMPUTE: begin\n                    result_count <= 4'd0;\n                    if (!conflict) begin\n                        if (black_count > 0) begin\n                            result_addr[0] <= black_start[0];\n                            temp_end = black_end[0] - black_start[0] + 1;\n                            result_mask[0] <= 4'd8 - temp_end;\n                            result_count <= 4'd1;\n                        end else begin\n                            result_addr[0] <= 8'h00;\n                            result_mask[0] <= 4'd0;\n                            result_count <= 4'd1;\n                        end\n                    end\n                end\n                \n                OUTPUT: begin\n                    done <= 1'b1;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule